        // Never combine a water-relative angle with ground-relative speed. Prefer
        // water VMG (STW/TWA); only fall back to a fully ground-referenced vector.
        val vmg=VmgReferencePolicy.calculate(freshStw.value,freshTwa.value,freshSog.value,freshCog.value,freshTwd.value)?.let{result->projectedSpeed(result.knots,0.0,now,result.provenance)}?:VesselObservation()
        val vmc=projectedSpeed(freshSog.value,freshCog.value?.let{course->freshWaypointBearing.value?.let{bearing->signedAngle(course-bearing)}},now,"SOG × cos(COG-bearing)")
        val estimatedCurrent=estimateCurrent(freshSog.value,freshCog.value,freshStw.value,selectedHeading.value,now)
        val selectedMagnetic=selectionObservation(registrySelection<Double>(VesselMetricId.HEADING_MAGNETIC,headingPreference,pinnedHeadingSourceId,now))?:if(selectedHeading.source==VesselDataSource.PHONE_MAGNETOMETER)classify(phoneMagneticHeadingValue,now,1_500,5_000) else classify(magneticHeading,now,5_000,30_000)
        val deviceTrue=selectionObservation(registrySelection<Double>(VesselMetricId.DEVICE_HEADING_TRUE,VesselSourcePreference.PHONE,null,now))?:VesselObservation();val deviceMagnetic=selectionObservation(registrySelection<Double>(VesselMetricId.DEVICE_HEADING_MAGNETIC,VesselSourcePreference.PHONE,null,now))?:VesselObservation()
        val sourceSnapshot=sourceRegistry.snapshot.value
        fun selectedMetric(metric:VesselMetricId,legacy:VesselObservation<Double>,fresh:Long,held:Long)=selectionObservation(registrySelection<Double>(metric,VesselSourcePreference.AUTO,null,now))?:classify(legacy,now,fresh,held)
        val sourceSelections=sourceSnapshot.keys.associateWith{metric->
            val preference=when(metric){VesselMetricId.POSITION->effectivePositionPreference;VesselMetricId.HEADING_TRUE,VesselMetricId.HEADING_MAGNETIC->headingPreference;else->VesselSourcePreference.AUTO}
            val pin=when(metric){VesselMetricId.POSITION->pinnedPositionSourceId;VesselMetricId.HEADING_TRUE,VesselMetricId.HEADING_MAGNETIC->pinnedHeadingSourceId;else->null}
            registrySelection<Any>(metric,preference,pin,now,excludeBoat=metric==VesselMetricId.POSITION&&phonePositionOutputEnabled)
        }
        val evaluatedCandidates=sourceSelections.mapValues{(_,selection)->selection.candidates}
        val conflicts=sourceSelections.mapNotNull{(metric,selection)->selection.conflict.takeIf{it.active}?.let{metric to it}}.toMap()
        _snapshot.value=VesselDataSnapshot(position=selectedPosition,sogKnots=freshSog,cogTrueDegrees=freshCog,headingTrueDegrees=selectedHeading,headingMagneticDegrees=selectedMagnetic,depthMeters=classifiedDepth,speedThroughWaterKnots=freshStw,trueWind=VesselWindObservation(freshTws,freshTwd,freshTwa),apparentWind=VesselWindObservation(freshAws,VesselObservation(),freshAwa),attitude=classify(attitudeValue,now,1_000,5_000),motion=classify(motionValue,now,2_000,10_000),pressureHpa=classifiedPressure,rateOfTurnDegreesPerMinute=selectedMetric(VesselMetricId.RATE_OF_TURN,rateOfTurn,5_000,30_000),rudderAngleDegrees=selectedMetric(VesselMetricId.RUDDER_ANGLE,rudderAngle,5_000,30_000),waterTemperatureCelsius=selectedMetric(VesselMetricId.WATER_TEMPERATURE,waterTemperature,30_000,5*60_000),airTemperatureCelsius=selectedMetric(VesselMetricId.AIR_TEMPERATURE,airTemperature,30_000,5*60_000),currentSetTrueDegrees=selectedMetric(VesselMetricId.CURRENT_SET,currentSet,10_000,60_000),currentDriftKnots=selectedMetric(VesselMetricId.CURRENT_DRIFT,currentDrift,10_000,60_000),crossTrackErrorNauticalMiles=selectedMetric(VesselMetricId.XTE,crossTrackError,10_000,60_000),waypointBearingTrueDegrees=selectionObservation(registrySelection(VesselMetricId.WAYPOINT_BEARING,VesselSourcePreference.AUTO,null,now))?:freshWaypointBearing,waypointDistanceNauticalMiles=selectedMetric(VesselMetricId.WAYPOINT_DISTANCE,waypointDistance,10_000,60_000),destinationWaypoint=selectionObservation(registrySelection(VesselMetricId.DESTINATION_WAYPOINT,VesselSourcePreference.AUTO,null,now))?:classify(destinationWaypoint,now,10_000,60_000),totalLogNauticalMiles=selectedMetric(VesselMetricId.TOTAL_LOG,totalLog,30_000,5*60_000),tripLogNauticalMiles=selectedMetric(VesselMetricId.TRIP_LOG,tripLog,30_000,5*60_000),derived=VesselDerivedSnapshot(underKeelClearanceMeters=ukc,headingCogDifferenceDegrees=headingCog,pressureTrend1hHpa=pressureTrend(60*60_000L),pressureTrend3hHpa=pressureTrend(3*60*60_000L),pressureTrend6hHpa=pressureTrend(6*60*60_000L),vmgToWindKnots=vmg,vmcToWaypointKnots=vmc,estimatedCurrentSetTrueDegrees=estimatedCurrent?.first?:VesselObservation(),estimatedCurrentDriftKnots=estimatedCurrent?.second?:VesselObservation()),deviceHeadingTrueDegrees=deviceTrue,deviceHeadingMagneticDegrees=deviceMagnetic,candidates=evaluatedCandidates,conflicts=conflicts,generatedElapsedRealtime=now)
    }
    @Synchronized private fun clearBoatGeneration(){boatPosition=VesselObservation();sog=VesselObservation();cog=VesselObservation();speedThroughWater=VesselObservation();boatHeading=VesselObservation();magneticHeading=VesselObservation();depthValue=VesselObservation();depthReference=null;trueWindSpeed=VesselObservation();trueWindDirection=VesselObservation();trueWindAngle=VesselObservation();apparentWindSpeed=VesselObservation();apparentWindAngle=VesselObservation();rateOfTurn=VesselObservation();rudderAngle=VesselObservation();waterTemperature=VesselObservation();airTemperature=VesselObservation();currentSet=VesselObservation();currentDrift=VesselObservation();crossTrackError=VesselObservation();waypointBearing=VesselObservation();waypointDistance=VesselObservation();destinationWaypoint=VesselObservation();totalLog=VesselObservation();tripLog=VesselObservation();arbitrator.reset();trueWindHysteresis.reset()}
    @Synchronized private fun invalidateLegacyBoatFields(event:NmeaSourceInvalidation){event.affectedMetrics.forEach{metric->when(metric){
        VesselMetricId.POSITION->boatPosition=VesselObservation();VesselMetricId.SOG->sog=VesselObservation();VesselMetricId.COG->cog=VesselObservation();VesselMetricId.SPEED_THROUGH_WATER->speedThroughWater=VesselObservation();VesselMetricId.DEPTH->depthValue=VesselObservation();
        VesselMetricId.HEADING_TRUE->boatHeading=VesselObservation();VesselMetricId.HEADING_MAGNETIC->magneticHeading=VesselObservation();VesselMetricId.TRUE_WIND_SPEED->trueWindSpeed=VesselObservation();VesselMetricId.TRUE_WIND_DIRECTION->trueWindDirection=VesselObservation();VesselMetricId.TRUE_WIND_ANGLE->trueWindAngle=VesselObservation();VesselMetricId.APPARENT_WIND_SPEED->apparentWindSpeed=VesselObservation();VesselMetricId.APPARENT_WIND_ANGLE->apparentWindAngle=VesselObservation();
        VesselMetricId.RATE_OF_TURN->rateOfTurn=VesselObservation();VesselMetricId.RUDDER_ANGLE->rudderAngle=VesselObservation();VesselMetricId.XTE->crossTrackError=VesselObservation();VesselMetricId.WAYPOINT_BEARING->waypointBearing=VesselObservation();VesselMetricId.WAYPOINT_DISTANCE->waypointDistance=VesselObservation();VesselMetricId.DESTINATION_WAYPOINT->destinationWaypoint=VesselObservation();else->Unit
    }}}
    private fun <T> registrySelection(metric:VesselMetricId,preference:VesselSourcePreference,pinnedId:String?,now:Long,excludeBoat:Boolean=false):VesselSourceSelection<T>{
        val candidates=sourceRegistry.candidates<T>(metric).filterNot{excludeBoat&&it.sourceClass==VesselSourceClass.BOAT_NMEA}
        val resolvedPin=pinnedId?.let{stored->VesselSourcePinPolicy.resolve(candidates,stored)?:stored}
        return arbitrator.select(metric,candidates,MetricSourcePreference(preference,resolvedPin,allowPinnedFallback),now)
    }
    private fun <T> selectionObservation(selection:VesselSourceSelection<T>):VesselObservation<T>?=selection.selected?.let{candidate->
        VesselObservation(value=candidate.value,source=candidate.sourceClass.toLegacySource(),observedAtUtcMillis=candidate.observedAtUtcMillis,receivedElapsedRealtime=candidate.receivedElapsedRealtime,quality=candidate.quality,freshness=if(candidate.sourceHeartbeatElapsedRealtime>candidate.receivedElapsedRealtime)VesselDataFreshness.HELD else VesselDataFreshness.FRESH,provenance=candidate.source.displayName,sourceIdentity=candidate.source,sourceClass=candidate.sourceClass,reference=candidate.reference,provenanceDetail=candidate.provenance,conflict=selection.conflict.takeIf{it.active},sourceHeartbeatElapsedRealtime=candidate.sourceHeartbeatElapsedRealtime,selectionReason=selection.reason)
    }
    private fun <T> classify(value:VesselObservation<T>,now:Long,fresh:Long,held:Long)=VesselFreshnessPolicy.classify(value,now,fresh,held)
    private fun <T> observation(value:T,source:VesselDataSource,received:Long?,observed:Long?,provenance:String?,quality:VesselDataQuality=VesselDataQuality.GOOD)=VesselObservation(value,source,observed,received,quality,VesselDataFreshness.FRESH,provenance)
    private fun <T> fieldObservation(field:NmeaFieldObservation,value:T)=observation(value,VesselDataSource.BOAT_NMEA,field.receivedElapsedRealtime,null,"${field.key.sentenceType}:${field.key.fieldIndex}${field.key.transducerName?.let{":$it"}.orEmpty()}")
    private fun projectedSpeed(speed:Double?,angle:Double?,now:Long,provenance:String):VesselObservation<Double>{if(speed==null||angle==null)return VesselObservation();return VesselObservation(speed*cos(Math.toRadians(angle)),VesselDataSource.DERIVED,receivedElapsedRealtime=now,quality=VesselDataQuality.GOOD,freshness=VesselDataFreshness.FRESH,provenance=provenance)}
    private fun signedAngle(value:Double)=((value+540.0)%360.0)-180.0
    private fun estimateCurrent(sog:Double?,cog:Double?,stw:Double?,heading:Double?,now:Long):Pair<VesselObservation<Double>,VesselObservation<Double>>?{if(sog==null||cog==null||stw==null||heading==null)return null;val groundEast=sog*sin(Math.toRadians(cog));val groundNorth=sog*cos(Math.toRadians(cog));val waterEast=stw*sin(Math.toRadians(heading));val waterNorth=stw*cos(Math.toRadians(heading));val east=groundEast-waterEast;val north=groundNorth-waterNorth;val drift=hypot(east,north);val set=(Math.toDegrees(atan2(east,north))+360.0)%360.0;val base=VesselObservation(set,VesselDataSource.DERIVED,receivedElapsedRealtime=now,quality=VesselDataQuality.DEGRADED,freshness=VesselDataFreshness.FRESH,provenance="ground velocity minus through-water velocity");return base to base.copy(value=drift)}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.sogOrNull()=speedOverGroundKnots?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"NMEA SOG")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.cogOrNull()=courseOverGroundTrue?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"NMEA COG")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.stwOrNull()=speedThroughWaterKnots?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"VHW")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.trueHeadingOrNull()=headingTrue?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,selectedHeadingSourceId?:"HDT/HDG/VHW",if(headingConflict)VesselDataQuality.DEGRADED else VesselDataQuality.GOOD)}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.magneticHeadingOrNull()=headingMagnetic?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,selectedHeadingSourceId?:"HDM/HDG/VHW",if(headingConflict)VesselDataQuality.DEGRADED else VesselDataQuality.GOOD)}
    private fun normalize(value:Double)=(value%360.0+360.0)%360.0
    private companion object{
        val PHONE_GNSS_ID=VesselSourceIdentity("phone:gnss",sourceType=VesselSourceType.PHONE_SENSOR,phoneSensorType="GNSS",displayName="Phone GNSS")
